def transform(grid):
    out = [row[:] for row in grid]
    # A long color-2 guide line and a small attached patch indicate the
    # parallel color-8 line, one column beyond the patch on its outer side.
    guide_col = next(c for c in range(len(grid[0])) if all(row[c] == 2 for row in grid))
    marked = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value not in (5, 2, 0)]
    if marked:
        cols = [c for _, c in marked]
        side = 1 if min(cols) > guide_col else -1
        target = (max(cols) if side == 1 else min(cols)) + side
        if 0 <= target < len(grid[0]):
            for r in range(len(grid)):
                out[r][target] = 8
    return out

